import{_ as a,C as n,o as r,c as i,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Passing Tests Is Not Operational Capability","description":"","frontmatter":{"title":"Passing Tests Is Not Operational Capability","date":"2026-09-05","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"在什么证据充分具备之后，才能把智能体生成并迭代的软件称为具有运行能力，而不只是通过了生成期间可用的功能测试？","summary":"A reproducible study of agentic programming shows that code can succeed on small functional checks and still deadlock, exhaust memory, crash, or time out at larger workloads or parallelism. Completion claims should preserve functional, process, failure-envelope, scaling, and reproducibility evidence separately.","sources":["research/analysis/Q-20260905-03-operational-capability-evidence.md"],"item_id":"Q-20260905-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-05-passing-tests-is-not-operational-capability-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-09-05-passing-tests-is-not-operational-capability.md","filePath":"en/engineering/2026-09-05-passing-tests-is-not-operational-capability.md","lastUpdated":1788754225000}'),l={name:"en/engineering/2026-09-05-passing-tests-is-not-operational-capability.md"};function c(d,e,p,u,h,m){const t=n("ArticleCover");return r(),i("div",null,[o(t,{image:"/assets/covers/daily-2026-09-05-passing-tests-is-not-operational-capability-editorial-v2.webp",kicker:"Open-source Engineering · Daily Research",title:"Passing Tests Is Not Operational Capability",summary:"A reproducible study of agentic programming shows that code can succeed on small functional checks and still deadlock, exhaust memory, crash, or time out at larger workloads or parallelism. Completion claims should preserve functional, process, failure-envelope, scaling, and reproducibility evidence separately.",version:"Q-20260905-03",status:"Daily Runtime V5 · 2026-09-05",languageHref:"/zh/engineering/2026-09-05-passing-tests-is-not-operational-capability",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="passing-tests-is-not-operational-capability" tabindex="-1">Passing Tests Is Not Operational Capability <a class="header-anchor" href="#passing-tests-is-not-operational-capability" aria-label="Permalink to &quot;Passing Tests Is Not Operational Capability&quot;">​</a></h1><p>A coding agent plans, consults documentation, writes tests, executes the program, repairs failures, and finally turns every available local check green. The code then reaches a larger parallel environment and deadlocks, exhausts memory, or times out. The failure is not that testing had no value. It is that the completion claim became stronger than the proposition those tests examined.</p><p>The core proposition is: <strong>functional success and a rich agent development trace are necessary but insufficient evidence of operational capability. A stronger completion claim requires a separate, risk-proportionate qualification gate over the workload, concurrency, resource, topology, and reproducibility dimensions that matter to the intended deployment.</strong> This model lets each evidence layer close only the question it actually tested.</p><h2 id="an-iterative-trace-matters-but-it-describes-what-was-exercised" tabindex="-1">An Iterative Trace Matters, but It Describes What Was Exercised <a class="header-anchor" href="#an-iterative-trace-matters-but-it-describes-what-was-exercised" aria-label="Permalink to &quot;An Iterative Trace Matters, but It Describes What Was Exercised&quot;">​</a></h2><p>The research object examines a reproducible study of agentic programming. The models do not produce code in one shot. They run a plan-generate-test-refine loop: creating validation harnesses and Julia kernels, consulting Julia documentation through a tool integration, executing and repairing programs, and then performing performance and scaling experiments. The public package includes prompts, generated code, tests, interaction logs, and runtime data.</p><p>That process record is much stronger than a bare code answer. It can show which tools the agent used, which tests it created, which failures it encountered, and how the implementation changed. It helps a reviewer audit what the final artifact was actually exposed to.</p><p>But a rich process does not create a complete environment. The generation and refinement setting did not reproduce the target supercomputer&#39;s full distributed-memory topology, process placement, resource constraints, and core counts. The trace establishes behavior in the admitted environment. It cannot supply operational conditions that the agent never encountered.</p><h2 id="scale-introduces-new-failure-propositions" tabindex="-1">Scale Introduces New Failure Propositions <a class="header-anchor" href="#scale-introduces-new-failure-propositions" aria-label="Permalink to &quot;Scale Introduces New Failure Propositions&quot;">​</a></h2><p>The same-date research object records that some generated implementations compiled and passed small correctness checks, then encountered deadlocks, oversubscription, out-of-memory failures, crashes, or timeouts as workload or parallelism increased. The failures appeared across different framework and task combinations. Some arose from generated scheduling, dependency, or data-management choices, so the result is not a general verdict that one framework class is inferior.</p><p>Small functional tests and target operation answer different questions. The first asks whether results are correct for admitted inputs. The second also asks whether concurrent work waits in a cycle, resource demand crosses a limit, progress survives a different process or data topology, and performance degrades beyond an acceptable boundary as scale changes.</p><p>A three-second example: a task queue completes ten jobs with one worker. That supports its basic scheduling and result logic. Relabeling the result “production concurrency qualified” would exceed the evidence. The governed path records functional acceptance first, then obtains separate operational evidence at relevant concurrency, queue depth, dependency latency, and resource ceilings.</p><h2 id="five-evidence-layers-should-not-collapse-into-one-green-state" tabindex="-1">Five Evidence Layers Should Not Collapse into One Green State <a class="header-anchor" href="#five-evidence-layers-should-not-collapse-into-one-green-state" aria-label="Permalink to &quot;Five Evidence Layers Should Not Collapse into One Green State&quot;">​</a></h2><p>A more accurate completion contract preserves five facts:</p><table tabindex="0"><thead><tr><th>Evidence layer</th><th>What it can support</th><th>What it cannot establish by itself</th></tr></thead><tbody><tr><td>Functional correctness</td><td>Correct result for admitted inputs and assertions</td><td>Scalability, resource safety, concurrency robustness</td></tr><tr><td>Development-process evidence</td><td>What the agent planned, tested, debugged, and refined</td><td>Deployment fitness or target-environment equivalence</td></tr><tr><td>Operational failure envelope</td><td>Deadlock, timeout, crash, or resource limits observed under tested loads</td><td>Universal safety beyond that envelope</td></tr><tr><td>Performance and scaling evidence</td><td>Measured behavior as workload and resources change</td><td>Correctness for all inputs or globally optimal performance</td></tr><tr><td>Transfer and reproducibility evidence</td><td>Whether prompts, versions, environments, artifacts, and measurements are traceable</td><td>Deterministic generation or population-level model reliability</td></tr></tbody></table><p>These layers are complementary. Functional acceptance is the first gate; passing it can justify the expense of operational qualification. Process records explain how an implementation emerged. Stress and scaling experiments reveal boundaries invisible to small tests. Environment and reproduction records allow others to decide how far the evidence may transfer.</p><p>The governance rule is simple: passing one layer may advance the lifecycle, but it must not close every stronger proposition. “Tests passed,” “the agent completed multiple repair rounds,” “the artifact ran at target scale,” and “the artifact is operationally qualified” remain separate facts.</p><h2 id="ordinary-engineering-should-translate-the-dimensions-not-copy-hpc-metrics" tabindex="-1">Ordinary Engineering Should Translate the Dimensions, Not Copy HPC Metrics <a class="header-anchor" href="#ordinary-engineering-should-translate-the-dimensions-not-copy-hpc-metrics" aria-label="Permalink to &quot;Ordinary Engineering Should Translate the Dimensions, Not Copy HPC Metrics&quot;">​</a></h2><p>The practical counterargument is that most changes do not justify supercomputer-scale evaluation. A pure function, one-time migration helper, or low-risk internal utility may have no meaningful concurrency or scaling requirement. Applying the same large qualification suite to every artifact would waste time and slow delivery.</p><p>Qualification should therefore match the claim and risk, not a universal benchmark. Functional and boundary tests may be sufficient for a small deterministic utility. A claim that a high-impact service can carry production traffic requires evidence about failures that emerge only in its target conditions.</p><p>For ordinary enterprise systems, the high-performance-computing dimensions can be translated into concurrent users, queue depth, dependency outages, retry storms, rate limits, restart and recovery behavior, data volume, memory ceilings, and connection-pool exhaustion. Not every dimension must be tested. The team must identify which ones could make the current completion claim false and obtain evidence for those.</p><p>A practical admission checklist is:</p><ol><li>Is the current claim functional acceptance, a successful trial, or production operational qualification?</li><li>Which load, concurrency, dependency, and resource facts appear only in the target environment?</li><li>Which facts did the executed tests examine, and which remain assumptions?</li><li>What happens on timeout, resource exhaustion, or partial failure—stop, recover, retry, or reconcile?</li><li>Can reviewers trace the model, tools, prompts, dependencies, hardware, artifact, and measurement versions?</li></ol><h2 id="reproducible-does-not-mean-generally-reliable" tabindex="-1">Reproducible Does Not Mean Generally Reliable <a class="header-anchor" href="#reproducible-does-not-mean-generally-reliable" aria-label="Permalink to &quot;Reproducible Does Not Mean Generally Reliable&quot;">​</a></h2><p>The study provides a paper, a Zenodo artifact, and a public reproduction repository. That makes the concrete experiments more inspectable than a summary or leaderboard alone. It is independent research evidence relative to this repository&#39;s first-party projects and can support observations and reported results within the study&#39;s conditions.</p><p>Reproducibility still has boundaries. Each model-problem-framework condition was generated once, so generation-to-generation variance was not estimated. The generation environment differed from the target supercomputer. Some comparisons lack non-Julia or vendor-optimized ground truth. Prompt constraints trade flexibility against comparability, and token and human-guidance costs are incomplete.</p><p>The package therefore does not define a universal production-readiness threshold, establish that one framework family is generally superior, or turn one artifact trajectory into population-level model reliability. Its strongest contribution is placing local functional success and target-environment failure on one inspectable evidence chain.</p><h2 id="evidence-boundary-and-open-questions" tabindex="-1">Evidence Boundary and Open Questions <a class="header-anchor" href="#evidence-boundary-and-open-questions" aria-label="Permalink to &quot;Evidence Boundary and Open Questions&quot;">​</a></h2><p>The bounded judgment is that an agent&#39;s plan-test-refine process supplies real development evidence, while small correctness tests supply functional evidence. If a claim concerns operational capability, the evaluation must additionally probe the failure dimensions material to the target system and disclose environment differences.</p><p>Open questions remain: how many independent generations are needed for model-reliability claims; how much target-environment information should be exposed during refinement without causing benchmark overfitting; which stress dimensions should be default for ordinary enterprise agents; how a durable completion receipt should represent the evidence layer that has closed; and how qualification depth should scale under cost constraints.</p><p>The next time an agent turns every test green, do not erase that real progress by dismissing it—and do not relabel it as production readiness. Ask a more precise question: which evidence layer is green, and which target conditions can still fail only under scale, concurrency, or resource pressure?</p><p><strong>Evidence and sources:</strong></p><ul><li><a href="https://zenodo.org/records/22299039" target="_blank" rel="noreferrer">Zenodo: Agentic AI Generated Julia Code on Supercomputers (research artifact record 22299039)</a></li><li><a href="https://arxiv.org/abs/2606.16534" target="_blank" rel="noreferrer">arXiv: Agentic AI Generated Julia Code on Supercomputers (paper 2606.16534)</a></li><li><a href="https://github.com/BaLinuss/Agentic-AI-Generated-Julia-Code-on-Supercomputers" target="_blank" rel="noreferrer">GitHub: BaLinuss/Agentic-AI-Generated-Julia-Code-on-Supercomputers (reproduction repository)</a></li></ul>',32))])}const f=a(l,[["render",c]]);export{y as __pageData,f as default};
